        "jp": "<ruby>時<rt>じ</rt></ruby><ruby>下<rt>か</rt></ruby>ますますご<ruby>清<rt>せい</rt></ruby><ruby>栄<rt>えい</rt></ruby>のことと、<span style='color:#d64045'>お<ruby>慶<rt>よろこ</rt></ruby>び<ruby>申<rt>もう</rt></ruby>し<ruby>上<rt>あ</rt></ruby>げます</span>。",
        "cn": "值此时节，谨祝贵方愈加兴旺。",
