        "source": { "original": "実験が成功しても失敗しても、レポートでは実験結果や適切な資料のデータをもとに「自分の」実験について科学的・論理的に記述しましょう。", "name": "名古屋大学「化学实验レポートの書き方」", "url": "https://www.ilas.nagoya-u.ac.jp/Chem_Exp/report.html", "type": "大学官方教材", "accessedAt": "2026-08-24" }
